 String get(String url)throws Exception{if(Thread.currentThread().isInterrupted())throw new InterruptedException();Request q=new Request.Builder().url(url).header("User-Agent","Mozilla/5.0 ShortRadar/0.3.1").header("Accept","application/json,text/csv,*/*").build();try(Response r=http.newCall(q).execute()){if(!r.isSuccessful())throw new IOException("HTTP "+r.code());if(r.body()==null)throw new IOException("空回應");return r.body().string().replaceFirst("^\\uFEFF","");}}
