 static JSONObject quote(JSONObject j){JSONObject o=new JSONObject();Double c=n(j,"收盤價","ClosingPrice","Close"),open=n(j,"開盤價","OpeningPrice","Open"),h=n(j,"最高價","HighestPrice","High"),l=n(j,"最低價","LowestPrice","Low"),v=n(j,"成交股數","TradeVolume","TradingShares"),ch=n(j,"漲跌價差","Change","漲跌");String sign=str(j,"漲跌(+/-)","漲跌(+-)","Dir").replaceAll("<[^>]+>","").trim();if(ch!=null&&!sign.isEmpty()){if(sign.equals("-"))ch=-Math.abs(ch);else if(sign.equals("+"))ch=Math.abs(ch);else if(ch!=0)ch=null;}put(o,"close",c);put(o,"open",open);put(o,"lots",v==null?null:v/1000);put(o,"change_pct",c!=null&&ch!=null&&c-ch>0?100*ch/(c-ch):null);put(o,"close_position",c!=null&&h!=null&&l!=null&&h>l&&c>=l&&c<=h?100*(c-l)/(h-l):null);return o;}
