 void twForeign(boolean prev){step("上市外資持股"+(prev?"與前期":""));try{LocalDate d=daily.get("TWSE");if(d==null)throw new IOException("缺收盤日期");Report r=tw("fund/MI_QFIIS","&selectType=ALLBUT0999",d,0,"證券代號","持股比率");Map<String,Double> cur=twForeignMap(r);for(String id:cur.keySet())attach(row("TWSE",id),"twforeign",r.date,"foreign",cur.get(id));put(sources,"上市外資",r.url);if(prev){try{Report old=tw("fund/MI_QFIIS","&selectType=ALLBUT0999",d.minusDays(1),6,"證券代號","持股比率");Map<String,Double> before=twForeignMap(old);for(String id:cur.keySet())if(before.containsKey(id))attach(row("TWSE",id),"twforeign_previous",old.date,"foreign_delta",cur.get(id)-before.get(id));put(sources,"上市前期外資",old.url);}catch(Exception e){error("上市前期外資",e.getMessage());}}}catch(Exception e){error("上市外資",e.getMessage());}}
 void tpQuotes(){step("上櫃收盤行情");try{String u=TP+"tpex_mainboard_daily_close_quotes";JSONArray a=list(u);LocalDate d=null;for(int i=0;i<a.length();i++){JSONObject x=obj(a,i);if(x==null)continue;LocalDate k=rd(x);if(fresh(k,today,7)&&(d==null||k.isAfter(d)))d=k;}if(d==null)throw new IOException("上櫃日期無法確認");daily.put("TPEX",d);int count=0;for(int i=0;i<a.length();i++){JSONObject x=obj(a,i);if(x==null||!d.equals(rd(x)))continue;JSONObject v=row("TPEX",sym(x));if(v!=null){merge(v,"tpquote",d,quote(x));count++;}}if(count==0)throw new IOException("沒有上櫃普通股");put(sources,"上櫃行情",u);}catch(Exception e){error("上櫃行情",e.getMessage());}}
 void tpMargin(){step("上櫃融資融券");try{String u=TP+"tpex_mainboard_margin_balance";LocalDate d=daily.get("TPEX");if(d==null)throw new IOException("缺收盤日期");JSONArray a=list(u);int count=0;for(int i=0;i<a.length();i++){JSONObject x=obj(a,i);if(x==null||!d.equals(rd(x)))continue;JSONObject v=row("TPEX",sym(x));if(v==null)continue;JSONObject m=margin(n(x,"MarginPurchaseBalancePreviousDay","PreviousMarginBalance","MarginPurchasePreviousBalance","前資餘額"),n(x,"MarginPurchaseBalance","MarginBalance","資餘額"),n(x,"ShortSaleBalancePreviousDay","PreviousShortBalance","ShortSalePreviousBalance","前券餘額"),n(x,"ShortSaleBalance","ShortBalance","券餘額"));merge(v,"tpmargin",d,m);if(!m.isNull("margin_delta")&&!m.isNull("short_delta"))count++;}if(count==0)throw new IOException("資券日期或欄位無有效值");put(sources,"上櫃資券",u);}catch(Exception e){error("上櫃資券",e.getMessage());}}
