 static JSONArray tdRows(String text)throws Exception{if(text.trim().startsWith("["))return new JSONArray(text);String[] lines=text.split("\\r?\\n");if(lines.length<2||!lines[0].contains("持股分級")||!lines[0].contains("資料日期"))throw new IOException("集保資料不是 CSV/JSON");JSONArray out=new JSONArray();String[] f=lines[0].replace("\"","").split(",",-1);for(int i=1;i<lines.length;i++){String[] v=lines[i].replace("\"","").split(",",-1);if(v.length!=f.length)continue;JSONObject x=new JSONObject();for(int k=0;k<f.length;k++)put(x,f[k].trim(),v[k].trim());out.put(x);}return out;}
 static Map<LocalDate,Map<String,double[]>> tiers(JSONArray a){Map<LocalDate,Map<String,double[]>> out=new TreeMap<>();for(int i=0;i<a.length();i++){JSONObject x=obj(a,i);if(x==null)continue;LocalDate d=rd(x);String s=sym(x);Double level=n(x,"持股分級","HoldingLevel"),v=n(x,"占集保庫存數比例%","佔集保庫存數比例%","占集保庫存數比例","占集保庫存比例","Proportion");if(d==null||s.isEmpty()||level==null||v==null||v<0||v>100||level!=Math.floor(level)||level<1||level>15)continue;double[] z=out.computeIfAbsent(d,k->new HashMap<>()).computeIfAbsent(s,k->{double[] q=new double[15];Arrays.fill(q,Double.NaN);return q;});int k=level.intValue()-1;if(!Double.isNaN(z[k])&&z[k]!=v)z[k]=Double.POSITIVE_INFINITY;else z[k]=v;}return out;}
 static double[] sums(double[] a){if(a==null)return null;double small=0,big=0,total=0;for(int i=0;i<15;i++){if(!Double.isFinite(a[i]))return null;total+=a[i];if(i<3)small+=a[i];if(i>=11)big+=a[i];}if(total<95||total>105)return null;return new double[]{big,small};}
 void tdcc(boolean prev){step("集保最新與前期持股級距");try{Map<LocalDate,Map<String,double[]>> data;String u=TD;try{data=tiers(tdRows(get(u)));if(data.isEmpty())throw new IOException("集保無資料");}catch(Exception e){u="https://opendata.tdcc.com.tw/getOD.ashx?id=1-5";data=tiers(tdRows(get(u)));}LocalDate d=null;for(LocalDate k:data.keySet())if(fresh(k,today,10)&&(d==null||k.isAfter(d)))d=k;if(d==null)throw new IOException("集保最新日期缺失或過期");put(sources,"集保最新",u);Map<String,double[]> cur=data.get(d),old=null;LocalDate od=null;if(prev){for(int b=5;b<=9;b++){LocalDate k=d.minusDays(b);if(data.containsKey(k)){old=data.get(k);od=k;break;}String a=ARCH+k.getYear()+"/"+k+".csv";try{Map<LocalDate,Map<String,double[]>> hist=tiers(tdRows(get(a)));if(hist.containsKey(k)&&hist.get(k).size()>100){old=hist.get(k);od=k;put(sources,"集保前期（第三方留存官方原始CSV）",a);break;}}catch(Exception ignored){}}if(old==null)error("集保前期","無法取得前一期完整級距");}int count=0;for(JSONObject r:rows.values()){String id=r.optString("symbol");double[] a=sums(cur.get(id)),b=old==null?null:sums(old.get(id));if(a==null)continue;count++;put(r,"small",a[1]);put(r.optJSONObject("dates"),"tdcc",d.toString());if(b!=null){put(r,"big_delta",a[0]-b[0]);put(r,"small_delta",a[1]-b[1]);put(r.optJSONObject("dates"),"tdcc_previous",od.toString());}}if(count==0)throw new IOException("集保級距無完整普通股");}catch(Exception e){error("集保",e.getMessage());}}
 static Boolean lt(JSONObject r,String k,double x){Double v=n(r,k);return v==null?null:v<x;}
